    21: [400, 100, 0], 22: [1100, 100, -5], 24: [2400, 100, 0], 25: [1000, 100, 0], 26: [1000, 100, 0], 27: [1400, 100, 0], 28: [1200, 100, 0],
    29: [1100, 100, 0], 30: [1000, 100, 0], 31: [1100, 100, 0], 32: [1600, 100, 0], 33: [1600, 100, 0], 34: [1500, 100, 0],
