      if (!vs) vs = maxRunH;
      var sp = SPO[spec.pp + ':' + vs] != null ? SPO[spec.pp + ':' + vs] : Math.round(vs * (pm.ls - 100) / 100);
      var tp = chars.length ? chars[Math.min(r.f, chars.length - 1)].off : 0;
      segs += '<hp:lineseg textpos="' + (chars.length ? tp : 0) + '" vertpos="' + vv + '" vertsize="' + vs + '" textheight="' + vs + '" baseline="' + Math.round(vs * 0.85) +
        '" spacing="' + sp + '" horzpos="' + left + '" horzsize="' + avail + '" flags="393216"/>';
      vv += vs + sp; lastSp = sp;
