    if (D.survey) prv.push('', '산 출 기 초 조 사 서', '일금: ' + koreanAmount(D.sum.cp));
    D.items.forEach(function (it) { prv.push(it.pname + ' ' + (it.spec || '-') + ' ' + it.qty + ' ' + fmt(it.cpTotal)); });
    if (D.insp) prv.push('', '물 품 검 수 조 서', '계약건명 ' + str(D.insp.contractName), '납품자 ' + str(D.insp.supplier));
